import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"第十一卦 泰 天地泰 坤上乾下","description":"周易 - 第十一卦 泰 天地泰 坤上乾下","frontmatter":{"title":"第十一卦 泰 天地泰 坤上乾下","description":"周易 - 第十一卦 泰 天地泰 坤上乾下"},"headers":[],"relativePath":"classics/zhouyi/012.md","filePath":"classics/zhouyi/012.md"}'),l={name:"classics/zhouyi/012.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="泰" tabindex="-1">泰 <a class="header-anchor" href="#泰" aria-label="Permalink to “泰”">​</a></h1><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>小往大來，吉亨。</p><h3 id="彖傳" tabindex="-1">彖傳 <a class="header-anchor" href="#彖傳" aria-label="Permalink to “彖傳”">​</a></h3><p>泰，小往大來，吉亨。則是天地交，而萬物通也；上下交，而其志同也。內陽而外陰，內健而外順，內君子而外小人，君子道長，小人道消也。</p><h3 id="象傳" tabindex="-1">象傳 <a class="header-anchor" href="#象傳" aria-label="Permalink to “象傳”">​</a></h3><p>天地交泰，後以財（裁）成天地之道，輔相天地之宜，以左右民。</p><h3 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h3><p>拔茅 茹，以其夤，徵吉。象曰：拔茅徵吉，志在外也。</p><h3 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h3><p>包荒，用馮河，不遐遺，朋亡，得尚於中行。象曰：包荒，得尚於中行，以光大也。</p><h3 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h3><p>無平不陂，無往不復，艱貞無咎。勿恤其孚，於食有福。象曰：無往不復，天地際也。</p><h3 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h3><p>翩翩不富，以其鄰，不戒以孚。象曰：翩翩不富，皆失實也。不戒以孚，中心願也。</p><h3 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h3><p>帝乙歸妹，以祉元吉。象曰：以祉元吉，中以行願也。</p><h3 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h3><p>城復於隍，勿用師。自邑告命，貞吝。象曰：城復於隍，其命亂也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
